function gauge({value:t,max:e,color:a,caption:n}){const l=230,r=160,$=120,i=76,o=Math.PI*t/e,s=(t,e)=>[l-e*Math.cos(t),r-e*Math.sin(t)],c=(t,e,a)=>{const[n,l]=s(0,$),[r,o]=s(t,$),[c,x]=s(t,i),[h,u]=s(0,i);return`<path ${a?`data-tip="${a}"`:""} d="M${n} ${l}A120 120 0 0 1 ${r} ${o}L${c} ${x}A76 76 0 0 0 ${h} ${u}Z" fill="${e}"/>`},[x,h]=s(o,70),u=7*Math.sin(o),p=7*-Math.cos(o),[d,m]=s(o,132),[y,g]=s(o,$),[b,f]=s(o,i);return`<svg class="chart gauge" viewBox="0 0 460 215">\n    ${c(Math.PI,C.gray)}\n    ${t?c(o,a,`${esc(n)} : ${t}`):""}\n    ${t&&t<e?`<line x1="${y}" y1="${g}" x2="${b}" y2="${f}" stroke="#333"/><text x="${d}" y="${m}" text-anchor="middle">${t}</text>`:""}\n    <polygon points="${x},${h} ${l+u},${r+p} ${l-u},${r-p}" fill="#777" stroke="#555"/>\n    <circle cx="230" cy="160" r="7" fill="#777" stroke="#555"/>\n    <text x="132" y="178" text-anchor="middle">0</text>\n    <text x="328" y="178" text-anchor="middle">${e}</text>\n    <text x="230" y="204" text-anchor="middle">${esc(n)}</text>\n  </svg>`}const chart=(t,e,a)=>{if(!e.length||!sum(e.map(t=>t.value)))return empty("Sin datos");const n=a?e.filter(t=>!a.has(t.label)):e;return{bar:()=>bars({labels:e.map(t=>t.label),lab:"out",series:[{values:e.map(t=>t.value),colors:e.map(t=>t.color)}]}),pie:()=>pie(n,!1,e,a),line:()=>line(e),area:()=>line(e,!0),donut:()=>pie(n,!0,e,a),funnel:()=>funnel(n),pyramid:()=>pyramid(n,e,a),hbar:()=>hbar(e)}[t]()};